-- Transactional acceptance tests. All identities and orders are rolled back.
begin;
do $$
declare c uuid:=gen_random_uuid(); muser uuid:=gen_random_uuid(); rider uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); adm uuid:=gen_random_uuid(); mid uuid; pid uuid; oid uuid; pickup uuid; blocked boolean; n int;
begin
 insert into auth.users(id,raw_user_meta_data) values(c,'{"display_name":"Test customer","role":"admin"}'),(muser,'{}'),(rider,'{}'),(outsider,'{}'),(adm,'{}');
 insert into public.user_roles values(adm,'admin'),(rider,'courier');
 insert into public.courier_applications(user_id,phone,transport,status,online) values(rider,'0000000000','Пешком','approved',true);
 insert into public.merchants(name,address,owner_id,approved,active,accepts_orders,cash_enabled,delivery_enabled) values('TEST ONLY','Тестовый адрес 123',muser,true,true,true,true,true) returning id into mid;
 insert into public.products(merchant_id,name,price_kopecks) values(mid,'Тестовый товар',29000) returning id into pid;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 if public.has_role('admin') then raise exception 'Metadata privilege escalation'; end if;
 blocked:=false;begin insert into public.user_roles values(c,'admin');exception when insufficient_privilege then blocked:=true;end;
 if not blocked then raise exception 'Role insertion allowed';end if;
 blocked:=false;begin perform public.review_application(mid,'merchant',true);exception when others then blocked:=true;end;
 if not blocked then raise exception 'Review allowed to customer';end if;
 blocked:=false;begin perform public.place_order(mid,jsonb_build_array(jsonb_build_object('product_id',pid,'quantity',null)),'delivery','Тестовый адрес 456');exception when others then blocked:=true;end;
 if not blocked then raise exception 'Null quantity accepted';end if;
 oid:=public.place_order(mid,jsonb_build_array(jsonb_build_object('product_id',pid,'quantity',2)),'delivery','Тестовый адрес 456');
 if not exists(select 1 from public.orders where id=oid and subtotal_kopecks=58000 and delivery_kopecks=11900) then raise exception 'Server totals invalid';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'role','authenticated')::text,true);
 select count(*) into n from public.orders where id=oid;if n<>0 then raise exception 'Order leaked';end if;
 select count(*) into n from public.order_items where order_id=oid;if n<>0 then raise exception 'Items leaked';end if;
 blocked:=false;begin perform public.transition_order(oid,'accepted');exception when others then blocked:=true;end;
 if not blocked then raise exception 'Foreign transition allowed';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',muser,'role','authenticated')::text,true);
 blocked:=false;begin update public.merchants set approved=false where id=mid;exception when others then blocked:=true;end;
 if not blocked then raise exception 'Merchant approval changed';end if;
 perform public.transition_order(oid,'accepted');perform public.transition_order(oid,'preparing');perform public.transition_order(oid,'ready');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',rider,'role','authenticated')::text,true);
 select count(*) into n from public.orders where id=oid;if n<>0 then raise exception 'Unassigned order address leaked';end if;
 select count(*) into n from public.available_deliveries() where id=oid;if n<>1 then raise exception 'Delivery missing';end if;
 perform public.claim_delivery(oid);
 blocked:=false;begin perform public.claim_delivery(oid);exception when others then blocked:=true;end;
 if not blocked then raise exception 'Double claim allowed';end if;
 perform public.transition_order(oid,'picked_up');perform public.transition_order(oid,'delivered');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);
 if not exists(select 1 from public.orders where id=oid and state='delivered') then raise exception 'Customer cannot see completion';end if;
 select count(*) into n from public.order_events where order_id=oid;if n<>7 then raise exception 'History incomplete: %',n;end if;
 pickup:=public.place_order(mid,jsonb_build_array(jsonb_build_object('product_id',pid,'quantity',1)),'pickup');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',muser,'role','authenticated')::text,true);
 perform public.transition_order(pickup,'accepted');perform public.transition_order(pickup,'preparing');perform public.transition_order(pickup,'ready');perform public.transition_order(pickup,'delivered');
 if not exists(select 1 from public.orders where id=pickup and state='delivered' and courier_id is null and delivery_kopecks=0) then raise exception 'Pickup invalid';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',adm,'role','authenticated')::text,true);
 select count(*) into n from public.orders where id in (oid,pickup);if n<>2 then raise exception 'Admin orders missing';end if;
 execute 'reset role';
 raise notice 'PASS: role escalation, RLS, totals, delivery, pickup, history and owner access';
end $$;
rollback;
